"use client";

/**
 * Designs panel: original sample artwork, generated in the browser.
 *
 * A new set appears every time the panel opens and on Shuffle. Clicking a
 * design fills the selected product box (drawn at that box's shape, so a
 * pattern covers a whole mug wrap) or places it on the page. The artwork is
 * generated by Sheetfit, so it can be printed and sold freely; web images
 * (Pinterest and the like) belong to their creators and are not offered.
 */

import { useState } from "react";
import { Shuffle } from "lucide-react";
import { useEditor } from "@/store/editor-store";
import { randomSeed, sampleSet, type SampleDesign } from "@/lib/catalogue/sample-designs";
import { sampleUrl } from "./sample-url";
import { findProduct } from "@/lib/catalogue/products";
import { applySampleDesign } from "@/lib/editor-actions";
import { Button } from "@/components/ui/button";
import { Note } from "@/components/settings/Section";

export function DesignsPanel() {
  const [seed, setSeed] = useState(randomSeed);
  const target = useEditor((s) => {
    const d = s.selection.length === 1 ? s.doc.designs.find((x) => x.id === s.selection[0]) : undefined;
    return d?.productId ? d : undefined;
  });
  const product = findProduct(target?.productId);
  const aspect = target ? target.width / target.height : 1;

  return (
    <div className="flex flex-col gap-4 p-4">
      <div className="flex items-start justify-between gap-3">
        <p className="text-[12.5px] leading-snug text-ink-muted">
          Original designs made by Sheetfit, free to print. A new set appears every time.
        </p>
        <Button size="sm" onClick={() => setSeed(randomSeed())}>
          <Shuffle />
          Shuffle
        </Button>
      </div>
      {product ? (
        <Note>
          Click a design to put it on the selected <span className="font-semibold text-ink">{product.name.toLowerCase()}</span>{" "}
          ({product.detail.toLowerCase()}).
        </Note>
      ) : (
        <Note>Select a product box first to fill it, or click a design to place it on the page.</Note>
      )}
      <DesignGrid title="Emblems" hint="Transparent background, for shirts, caps and totes" designs={sampleSet(seed, 8, "emblem")} aspect={aspect} />
      <DesignGrid title="Patterns" hint="Edge to edge, for mugs, tumblers and flat goods" designs={sampleSet(seed + 1, 6, "pattern")} aspect={aspect} />
    </div>
  );
}

function DesignGrid({ title, hint, designs, aspect }: { title: string; hint: string; designs: SampleDesign[]; aspect: number }) {
  return (
    <section>
      <h3 className="text-[13px] font-semibold">{title}</h3>
      <p className="mb-2 text-[11.5px] text-ink-muted">{hint}</p>
      <ul className="grid grid-cols-2 gap-2">
        {designs.map((d) => (
          <li key={d.id}>
            <button
              type="button"
              onClick={() => void applySampleDesign(d)}
              className="group block w-full text-left"
              aria-label={`Use sample design ${d.name}`}
            >
              <span className="checker flex aspect-square items-center justify-center overflow-hidden rounded-lg ring-1 ring-line transition group-hover:ring-2 group-hover:ring-accent">
                {/* eslint-disable-next-line @next/next/no-img-element -- generated SVG data URL */}
                <img src={sampleUrl(d, Math.min(2, Math.max(0.5, aspect)))} alt="" className="max-h-full max-w-full transition-transform duration-200 group-hover:scale-[1.04]" />
              </span>
              <span className="mt-1 block truncate text-[12px] font-medium">{d.name}</span>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}
